//! Map data: SVG geometry (`/assets/map_geometry.json`, regenerated by `scripts/mapgen`) plus the
//! engine's `map.json` (names, IPC values, original owners, starting units), copied into `assets/`
//! by `build.rs`.
//!
//! Geometry schema: `{"view_box":"0 0 2000 1000","projection":"miller","locations":{"<id>":
//! {"kind":"land|sea","path":"..","label":[x,y],"anchor":[x,y],"bbox":[x0,y0,x1,y1]}},"decor":"<path>"}`.
use crate::model::{Power, UnitKind};
use gloo_net::http::Request;
use serde::Deserialize;
use std::collections::HashMap;
use std::sync::Arc;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize, Default)]
#[serde(rename_all = "lowercase")]
pub enum LocKind {
    #[default]
    Land,
    Sea,
}

#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct RawLocation {
    #[serde(default)]
    pub kind: LocKind,
    pub path: String,
    #[serde(default)]
    pub label: Option<(f64, f64)>,
    #[serde(default)]
    pub anchor: Option<(f64, f64)>,
    #[serde(default)]
    pub bbox: Option<[f64; 4]>,
}

#[derive(Debug, Deserialize)]
struct RawGeometry {
    view_box: String,
    locations: HashMap<String, RawLocation>,
    #[serde(default)]
    decor: Option<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Location {
    pub id: String,
    pub kind: LocKind,
    pub path: String,
    pub label: (f64, f64),
    pub anchor: (f64, f64),
    /// `[x0, y0, x1, y1]` in viewBox units.
    pub bbox: [f64; 4],
}

#[derive(Debug, Clone, PartialEq)]
pub struct Geometry {
    pub view_box: [f64; 4],
    pub locations: Vec<Location>,
    pub decor: Option<String>,
}

impl Geometry {
    pub fn parse(json: &str) -> Result<Geometry, String> {
        let raw: RawGeometry = serde_json::from_str(json).map_err(|e| e.to_string())?;
        let v: Vec<f64> = raw
            .view_box
            .split_whitespace()
            .filter_map(|t| t.parse().ok())
            .collect();
        let view_box = <[f64; 4]>::try_from(v).map_err(|_| "bad view_box".to_string())?;
        let mut locations: Vec<Location> = raw
            .locations
            .into_iter()
            .map(|(id, l)| {
                let bbox = l.bbox.unwrap_or([0.0; 4]);
                let centre = l
                    .bbox
                    .map(|b| ((b[0] + b[2]) / 2.0, (b[1] + b[3]) / 2.0))
                    .unwrap_or((0.0, 0.0));
                let anchor = l.anchor.unwrap_or(centre);
                Location {
                    id,
                    kind: l.kind,
                    path: l.path,
                    label: l.label.unwrap_or(anchor),
                    anchor,
                    bbox,
                }
            })
            .collect();
        locations.sort_by(|a, b| a.id.cmp(&b.id));
        Ok(Geometry {
            view_box,
            locations,
            decor: raw.decor.filter(|d| !d.is_empty()),
        })
    }
}

#[derive(Debug, Clone, Deserialize)]
struct RawTerritory {
    id: String,
    name: String,
    #[serde(default)]
    ipc: u32,
    #[serde(default)]
    original_owner: Option<String>,
    #[serde(default)]
    is_capital: bool,
    #[serde(default)]
    industrial_complex: bool,
}

#[derive(Debug, Clone, Deserialize)]
struct RawSea {
    id: String,
    name: String,
}

#[derive(Debug, Clone, Deserialize)]
struct RawStart {
    location: String,
    owner: String,
    unit: String,
    count: u32,
}

#[derive(Debug, Deserialize)]
struct RawMap {
    territories: Vec<RawTerritory>,
    sea_zones: Vec<RawSea>,
    #[serde(default)]
    starting_units: Vec<RawStart>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct LocInfo {
    pub name: String,
    /// Short label (sea zones drop the "Sea Zone" suffix).
    pub short: String,
    pub ipc: u32,
    pub owner: Option<Power>,
    pub capital: bool,
    pub factory: bool,
}

#[derive(Debug, Clone, PartialEq)]
pub struct MapData {
    pub info: HashMap<String, LocInfo>,
    /// (location, owner, unit, count)
    pub starting_units: Vec<(String, Power, UnitKind, u32)>,
}

impl MapData {
    pub fn parse(json: &str) -> Result<MapData, String> {
        let raw: RawMap = serde_json::from_str(json).map_err(|e| e.to_string())?;
        let mut info = HashMap::new();
        for t in raw.territories {
            info.insert(
                t.id,
                LocInfo {
                    short: t.name.clone(),
                    name: t.name,
                    ipc: t.ipc,
                    owner: t.original_owner.as_deref().and_then(Power::parse),
                    capital: t.is_capital,
                    factory: t.industrial_complex,
                },
            );
        }
        for s in raw.sea_zones {
            let short = s
                .name
                .trim_end_matches(" Sea Zone")
                .trim_start_matches("Sea Zone ")
                .to_string();
            info.insert(
                s.id,
                LocInfo {
                    name: s.name,
                    short,
                    ipc: 0,
                    owner: None,
                    capital: false,
                    factory: false,
                },
            );
        }
        let starting_units = raw
            .starting_units
            .into_iter()
            .filter_map(|u| {
                Some((
                    u.location,
                    Power::parse(&u.owner)?,
                    UnitKind::from_id(&u.unit)?,
                    u.count,
                ))
            })
            .collect();
        Ok(MapData {
            info,
            starting_units,
        })
    }

    pub fn name<'a>(&'a self, id: &'a str) -> &'a str {
        self.info.get(id).map(|i| i.name.as_str()).unwrap_or(id)
    }
}

/// Everything the board needs, shared via `Arc` between the app context and pages.
#[derive(Debug, Clone, PartialEq)]
pub struct MapInfo {
    pub geo: Geometry,
    pub data: MapData,
}

pub type SharedMap = Arc<MapInfo>;

/// Stable 0/1 choice from a location id (FNV-1a), used to alternate the two sea blues.
pub fn sea_shade(id: &str) -> bool {
    let mut h: u32 = 0x811c_9dc5;
    for b in id.bytes() {
        h ^= b as u32;
        h = h.wrapping_mul(0x0100_0193);
    }
    (h >> 7) & 1 == 1
}

/// Abbreviations for land labels that do not fit their territory at the whole-map zoom.
/// Anything not listed falls back to the first four letters plus a dot.
const ABBREVS: &[(&str, &str)] = &[
    ("ukraine_s_s_r", "Ukr."),
    ("eastern_europe", "E. Eur."),
    ("western_europe", "W. Eur."),
    ("southern_europe", "S. Eur."),
    ("karelia_s_s_r", "Kar."),
    ("kazakh_s_s_r", "Kaz."),
    ("yakut_s_s_r", "Yak."),
    ("evenki_national_okrug", "Evenki"),
    ("soviet_far_east", "Far East"),
    ("finland_norway", "Fin./Nor."),
    ("united_kingdom", "U.K."),
    ("anglo_egypt_sudan", "Egypt"),
    ("french_west_africa", "Fr. W. Afr."),
    ("french_equatorial_africa", "Fr. Eq. Afr."),
    ("italian_east_africa", "It. E. Afr."),
    ("south_africa", "S. Afr."),
    ("kenya_rhodesia", "Kenya"),
    ("french_indo_china", "Indo-China"),
    ("east_indies", "E. Indies"),
    ("borneo_celebes", "Borneo"),
    ("new_guinea", "N. Guinea"),
    ("new_zealand", "N.Z."),
    ("solomon_islands", "Solomon"),
    ("caroline_islands", "Caroline"),
    ("hawaiian_islands", "Hawaii"),
    ("wake_island", "Wake"),
    ("western_canada", "W. Canada"),
    ("eastern_canada", "E. Canada"),
    ("western_usa", "W. USA"),
    ("eastern_usa", "E. USA"),
    ("argentina_chile", "Arg./Chile"),
    ("rio_del_oro", "Rio d. Oro"),
    ("saudi_arabia", "Saudi"),
    ("syria_iraq", "Syria-Iraq"),
];

/// Label font size (viewBox units, before the `--zs` overlay scale) at the whole-map zoom.
pub const LABEL_FONT_L0: f64 = 14.0;
/// Average glyph advance in em, including the CSS letter-spacing.
const GLYPH_EM: f64 = 0.6;

pub fn abbrev(id: &str, name: &str) -> String {
    if let Some((_, a)) = ABBREVS.iter().find(|(k, _)| *k == id) {
        return (*a).to_string();
    }
    let head: String = name.chars().take(4).collect();
    format!("{head}.")
}

fn text_width(text: &str, font: f64) -> f64 {
    text.chars().count() as f64 * GLYPH_EM * font
}

/// What to draw for a land territory at the whole-map zoom: the full name if it fits inside
/// `bbox` (at overlay scale 1, the widest it ever gets at that zoom), else the abbreviation if
/// that fits, else nothing.
pub fn fit_label(id: &str, name: &str, bbox: [f64; 4], font: f64) -> Option<String> {
    let avail = (bbox[2] - bbox[0]) * 0.95;
    if text_width(name, font) <= avail {
        return Some(name.to_string());
    }
    let short = abbrev(id, name);
    (text_width(&short, font) <= avail).then_some(short)
}

async fn fetch_text(url: &str) -> Result<String, String> {
    let resp = Request::get(url).send().await.map_err(|e| e.to_string())?;
    if !resp.ok() {
        return Err(format!("{url}: {}", resp.status()));
    }
    resp.text().await.map_err(|e| e.to_string())
}

pub async fn load() -> Result<SharedMap, String> {
    let geo = Geometry::parse(&fetch_text("/assets/map_geometry.json").await?)
        .map_err(|e| format!("map_geometry.json: {e}"))?;
    let data = MapData::parse(&fetch_text("/assets/map.json").await?)
        .map_err(|e| format!("map.json: {e}"))?;
    Ok(Arc::new(MapInfo { geo, data }))
}

#[cfg(test)]
mod label_tests {
    use super::*;

    #[test]
    fn fit_and_abbreviate() {
        // Wide territory: full name.
        let canada = [160.0, 0.0, 600.0, 290.0];
        assert_eq!(
            fit_label("western_canada", "Western Canada", canada, LABEL_FONT_L0).as_deref(),
            Some("Western Canada")
        );
        // Ukraine is ~100 wide: the full name does not fit, the abbreviation does.
        let ukr = [1067.4, 259.8, 1167.4, 316.0];
        assert_eq!(
            fit_label("ukraine_s_s_r", "Ukraine S.S.R.", ukr, LABEL_FONT_L0).as_deref(),
            Some("Ukr.")
        );
        let ee = [1013.6, 241.1, 1109.5, 336.9];
        assert_eq!(
            fit_label("eastern_europe", "Eastern Europe", ee, LABEL_FONT_L0).as_deref(),
            Some("E. Eur.")
        );
        // A speck of an island gets nothing.
        let dot = [100.0, 100.0, 106.0, 104.0];
        assert_eq!(fit_label("midway", "Midway", dot, LABEL_FONT_L0), None);
    }

    #[test]
    fn abbrev_fallback() {
        assert_eq!(abbrev("germany", "Germany"), "Germ.");
        assert_eq!(abbrev("ukraine_s_s_r", "Ukraine S.S.R."), "Ukr.");
    }
}
